// Real application roles and RLS. Generated bytes only; M4 transcript/store-fence doubles are explicit.
import { randomUUID } from 'node:crypto';
import pg from 'pg';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { AppError, type ObjectStore } from '@ensemus/application';
import { addUploadedSource } from '@ensemus/application/knowledge/sources';
import { ingestDocument } from '@ensemus/application/knowledge/ingest';
import { askQuestion, getAnswer } from '@ensemus/application/knowledge/answers';
import {
  deleteSource,
  getPurgeStatus,
  purgeRunTranscriptsForSource,
  revokeSource,
  runSourcePurge,
  claimSourcePurgeRetries,
} from '@ensemus/application/knowledge/purge';
import { proposeFact, reviewFact } from '@ensemus/application/knowledge/facts';
import type {
  RunTranscriptPurge,
  DerivedArtifactPurge,
} from '@ensemus/application/knowledge/ports';
import type { RecoverableKnowledgeStore } from '../../packages/application/src/knowledge/object-writes';
import {
  createOrganization,
  knowledgeAnswers,
  knowledgeAnswerSources,
  knowledgeDocuments,
  knowledgeFacts,
  knowledgeObjectWriters,
  knowledgePurgeJobs,
  knowledgeSources,
  openAppDatabase,
  resolveTenantContext,
  withTenantTx,
  type TenantContext,
} from '@ensemus/database';
import { createServiceContext } from '@ensemus/database/service';
import { parseDocument } from '@ensemus/knowledge/parsing';
import { eq, sql } from 'drizzle-orm';
import { seedMember } from '../helpers/knowledge';
import { urls } from '../helpers/stack';
import { pgCode } from '../../packages/application/src/errors';

describe('closed sources purge only after durable writer and transcript fences', () => {
  let database: ReturnType<typeof openAppDatabase>, auth: pg.Client;
  let owner: TenantContext, reader: TenantContext, reviewer: TenantContext, foreign: TenantContext;
  const bytes = new Map<string, Buffer>();
  let deleteUnavailable = false;
  const store: ObjectStore = {
    put: async (key, body) => {
      bytes.set(key, Buffer.from(body));
    },
    get: async (key) => {
      const body = bytes.get(key);
      if (!body) throw new Error('MISSING');
      return Buffer.from(body);
    },
    delete: async (key) => {
      if (deleteUnavailable) throw new Error('Generated unavailable store');
      bytes.delete(key);
    },
    exists: async (key) => bytes.has(key),
  };
  const service = () => createServiceContext(owner.organizationId);
  const transcripts: RunTranscriptPurge = {
    fenceUsing: async () => ({ fenced: true }),
    purgeUsing: async () => ({ removed: 0, remaining: 0 }),
  };
  // Explicit empty-artifact fixture. Real generated-artifact erasure is covered by 0208's adapter tests.
  const noDerivedArtifacts: DerivedArtifactPurge = {
    purgeSource: async () => ({ removed: 0, remaining: 0, held: 0, confirmed: true }),
    confirmInTx: async () => ({ remaining: 0 }),
  };
  const proof = (sourceId: string, port = transcripts) =>
    purgeRunTranscriptsForSource(database.db, service(), { transcripts: port }, { sourceId });
  const purge = (
    sourceId: string,
    objects: ObjectStore = store,
    derivedArtifacts: DerivedArtifactPurge = noDerivedArtifacts,
  ) => runSourcePurge(database.db, objects, service(), { sourceId }, { derivedArtifacts });
  const upload = async () => {
    const created = await addUploadedSource(database.db, store, owner, {
      title: 'Generated purge file',
      mediaType: 'text/plain',
      body: Buffer.from('Generated evidence for reliable source deletion.'),
      classification: 'internal',
      grants: [{ kind: 'organization' }],
    });
    await ingestDocument(
      database.db,
      store,
      service(),
      {
        parse: async (body, type) => parseDocument(body, type),
        contentScan: { scan: () => ({ raiseTo: null, codes: [] }) },
      },
      { documentId: created.documentId },
    );
    return created;
  };
  const close = (sourceId: string) =>
    revokeSource(database.db, owner, { sourceId, expectedVersion: 1, reason: 'Generated reason' });
  beforeAll(async () => {
    database = openAppDatabase(urls.app());
    auth = new pg.Client({ connectionString: urls.auth() });
    await auth.connect();
    const makeOwner = async () => {
      const userId = randomUUID();
      await auth.query('insert into identity.users(id,name,email) values($1,$2,$3)', [
        userId,
        'Generated person',
        `${userId}@example.invalid`,
      ]);
      const org = await createOrganization(database.db, {
        userId,
        name: 'Generated company',
        commercialMode: 'sovereign',
      });
      return resolveTenantContext(database.db, userId, org.organizationId);
    };
    owner = await makeOwner();
    foreign = await makeOwner();
    const member = await seedMember(database.db, owner, auth);
    reader = await resolveTenantContext(database.db, member.userId, owner.organizationId);
    const admin = await seedMember(database.db, owner, auth, 'admin');
    reviewer = await resolveTenantContext(database.db, admin.userId, owner.organizationId);
  });
  afterAll(async () => {
    await auth?.end();
    await database?.close();
  });

  it('rejects a member, service, other tenant and stale version without closing anything', async () => {
    const source = await upload();
    const input = { sourceId: source.sourceId, expectedVersion: 1, reason: 'Generated' };
    for (const context of [reader, service()])
      await expect(revokeSource(database.db, context, input)).rejects.toEqual(
        new AppError('FORBIDDEN'),
      );
    await expect(revokeSource(database.db, foreign, input)).rejects.toEqual(
      new AppError('NOT_FOUND'),
    );
    await expect(
      revokeSource(database.db, owner, { ...input, expectedVersion: 9 }),
    ).rejects.toEqual(new AppError('VERSION_CONFLICT'));
    expect(
      (
        await withTenantTx(database.db, service(), (tx) =>
          tx.select().from(knowledgeSources).where(eq(knowledgeSources.id, source.sourceId)),
        )
      )[0]?.state,
    ).toBe('active');
  });
  it('blocks an existing answer immediately and closes exactly once, before the purge runs', async () => {
    const source = await upload();
    const answer = await askQuestion(database.db, reader, {
      question: 'Generated question',
      classification: 'internal',
    });
    await withTenantTx(database.db, service(), async (tx) => {
      await tx.insert(knowledgeAnswerSources).values({
        organizationId: owner.organizationId,
        answerId: answer.answerId,
        sourceId: source.sourceId,
      });
      await tx
        .update(knowledgeAnswers)
        .set({ state: 'answered', answerText: 'Generated derived words.' })
        .where(eq(knowledgeAnswers.id, answer.answerId));
    });
    expect((await getAnswer(database.db, reader, answer.answerId)).answerText).toContain('derived');
    const first = await close(source.sourceId);
    expect(await close(source.sourceId)).toEqual(first);
    await expect(getAnswer(database.db, reader, answer.answerId)).rejects.toEqual(
      new AppError('NOT_FOUND'),
    );
    expect((await purge(source.sourceId)).state).toBe('failed');
    expect((await getPurgeStatus(database.db, owner, source.sourceId)).lastErrorCode).toBe(
      'TRANSCRIPT_PURGE_UNCONFIRMED',
    );
    await expect(
      proof(source.sourceId, { purgeUsing: async () => ({ removed: 0 }) }),
    ).rejects.toThrow('TRANSCRIPT_PURGE_UNCONFIRMED');
    await proof(source.sourceId);
    const completed = await purge(source.sourceId);
    expect(completed).toMatchObject({ state: 'completed', documents: 1, answers: 1, blobs: 1 });
    expect(completed.chunks).toBeGreaterThan(0);
    expect(await purge(source.sourceId)).toEqual(completed);
    const events = await withTenantTx(database.db, service(), (tx) =>
      tx.execute<{ kind: string; count: string }>(
        sql`select event_type as kind,count(*)::text as count from platform.domain_events where organization_id=${owner.organizationId}::uuid and aggregate_id=${source.sourceId}::uuid group by event_type`,
      ),
    );
    expect(
      events.rows.filter((row) =>
        ['tombstone.recorded', 'knowledge.source_closed', 'knowledge.purge_completed'].includes(
          row.kind,
        ),
      ),
    ).toHaveLength(3);
    expect(events.rows.every((row) => row.count === '1')).toBe(true);
  });
  it('keeps a store outage failed and blocked, then resumes with stable projection counts', async () => {
    const source = await upload();
    await deleteSource(database.db, owner, {
      sourceId: source.sourceId,
      expectedVersion: 1,
      reason: 'Generated deletion',
    });
    await proof(source.sourceId);
    deleteUnavailable = true;
    let failed;
    try {
      failed = await purge(source.sourceId);
    } finally {
      deleteUnavailable = false;
    }
    expect(failed).toMatchObject({ state: 'failed', documents: 0, blobs: 0 });
    expect((await getPurgeStatus(database.db, owner, source.sourceId)).lastErrorCode).toBe(
      'STORE_UNAVAILABLE',
    );
    await proof(source.sourceId);
    const done = await purge(source.sourceId);
    expect(done).toMatchObject({
      state: 'completed',
      documents: 1,
      blobs: 1,
      chunks: failed!.chunks,
    });
  });
  it('cannot report completion while a put is in flight; late publication cleans up and settles its own generation', async () => {
    let release!: () => void, start!: () => void;
    const began = new Promise<void>((resolve) => {
      start = resolve;
    });
    const pause = new Promise<void>((resolve) => {
      release = resolve;
    });
    const delayed: ObjectStore = {
      ...store,
      put: async (key, body) => {
        start();
        await pause;
        await store.put(key, body, 'text/plain');
      },
    };
    const request = addUploadedSource(database.db, delayed, owner, {
      title: 'Generated delayed upload',
      mediaType: 'text/plain',
      body: Buffer.from('Generated delayed bytes'),
      classification: 'internal',
      grants: [],
    }).then(
      (value) => ({ value, error: null }),
      (error) => ({ value: null, error }),
    );
    await began;
    const [writer] = await withTenantTx(database.db, service(), (tx) =>
      tx.select().from(knowledgeObjectWriters).where(eq(knowledgeObjectWriters.state, 'active')),
    );
    expect(writer).toBeDefined();
    await close(writer!.sourceId);
    await proof(writer!.sourceId);
    expect((await purge(writer!.sourceId)).state).toBe('failed');
    expect((await getPurgeStatus(database.db, owner, writer!.sourceId)).lastErrorCode).toBe(
      'OBJECT_WRITER_UNCONFIRMED',
    );
    release();
    expect((await request).error).toEqual(new AppError('KNOWLEDGE_SOURCE_CLOSED'));
    await proof(writer!.sourceId);
    expect((await purge(writer!.sourceId)).state).toBe('completed');
    expect([...bytes.keys()].some((key) => key.endsWith(writer!.documentId))).toBe(false);
  });
  it('requires explicit quiescence to recover a crashed writer, regardless of its age or object absence', async () => {
    await expect(
      addUploadedSource(
        database.db,
        {
          ...store,
          put: async () => {
            throw new Error('Unknown write outcome');
          },
        },
        owner,
        {
          title: 'Generated interrupted upload',
          mediaType: 'text/plain',
          body: Buffer.from('Generated interrupted bytes'),
          classification: 'internal',
          grants: [],
        },
      ),
    ).rejects.toEqual(new AppError('INVALID_STATE'));
    const [writer] = await withTenantTx(database.db, service(), (tx) =>
      tx.select().from(knowledgeObjectWriters).where(eq(knowledgeObjectWriters.state, 'active')),
    );
    await close(writer!.sourceId);
    await proof(writer!.sourceId);
    const objects: RecoverableKnowledgeStore = {
      ...store,
      fenceKnowledgeWrite: async () => ({ quiescent: false }),
    };
    expect((await purge(writer!.sourceId, objects)).state).toBe('failed');
    objects.fenceKnowledgeWrite = async (input) => {
      expect(input.writeId).toBe(writer!.writeId);
      expect(input.generation).toBe(writer!.generation);
      return { quiescent: true };
    };
    expect((await purge(writer!.sourceId, objects)).state).toBe('completed');
  });
  it('demotes a verified multi-source fact atomically and deletes a fact with no surviving evidence', async () => {
    const a = await upload(),
      b = await upload();
    const chunks = await withTenantTx(database.db, service(), (tx) =>
      tx.execute<{ id: string; sourceId: string }>(
        sql`select id,source_id as "sourceId" from knowledge.chunks where organization_id=${owner.organizationId}::uuid and source_id in (${a.sourceId}::uuid,${b.sourceId}::uuid) order by source_id`,
      ),
    );
    const evidence = chunks.rows.map((row) => ({ chunkId: row.id, quoteStart: 0, quoteEnd: 9 }));
    const multi = await proposeFact(database.db, owner, {
      subjectRef: `knowledge_source:${b.sourceId}`,
      predicate: 'relationship.note',
      claim: 'Generated multi-source claim',
      origin: 'person',
      evidence,
    });
    await reviewFact(database.db, reviewer, {
      factId: multi.factId,
      expectedVersion: 1,
      decision: 'verify',
      reason: 'Generated independent review',
    });
    const single = await proposeFact(database.db, owner, {
      subjectRef: `knowledge_source:${a.sourceId}`,
      predicate: 'relationship.note',
      claim: 'Generated single-source claim',
      origin: 'person',
      evidence: evidence.filter(
        (item) => chunks.rows.find((row) => row.id === item.chunkId)?.sourceId === a.sourceId,
      ),
    });
    await close(a.sourceId);
    await proof(a.sourceId);
    expect((await purge(a.sourceId)).state).toBe('completed');
    const facts = await withTenantTx(database.db, service(), (tx) =>
      tx.select().from(knowledgeFacts),
    );
    expect(facts.find((f) => f.id === multi.factId)).toMatchObject({
      trustState: 'disputed',
      conflictRef: `knowledge_source:${a.sourceId}`,
    });
    expect(facts.some((f) => f.id === single.factId)).toBe(false);
    expect(
      await withTenantTx(database.db, service(), (tx) =>
        tx.select().from(knowledgeDocuments).where(eq(knowledgeDocuments.sourceId, a.sourceId)),
      ),
    ).toEqual([]);
    expect(
      (
        await withTenantTx(database.db, service(), (tx) =>
          tx.select().from(knowledgePurgeJobs).where(eq(knowledgePurgeJobs.sourceId, a.sourceId)),
        )
      )[0]?.factsRemoved,
    ).toBe(1);
  });
  it('durably backs off and caps automatic workflow restart requests without reopening or resetting counts', async () => {
    const source = await upload();
    await close(source.sourceId);
    await purge(source.sourceId);
    await expect(claimSourcePurgeRetries(database.db, owner)).rejects.toEqual(
      new AppError('FORBIDDEN'),
    );
    for (let request = 1; request <= 8; request++) {
      await withTenantTx(database.db, service(), (tx) =>
        tx
          .update(knowledgePurgeJobs)
          .set({ nextRetryAt: new Date(Date.now() - 1000) })
          .where(eq(knowledgePurgeJobs.sourceId, source.sourceId)),
      );
      expect(
        (await claimSourcePurgeRetries(database.db, service())).some(
          (row) => row.sourceId === source.sourceId,
        ),
      ).toBe(true);
      const status = await getPurgeStatus(database.db, owner, source.sourceId);
      expect(status.retryRequests).toBe(request);
      expect(status.state).toBe('failed');
      expect(
        (await claimSourcePurgeRetries(database.db, service())).some(
          (row) => row.sourceId === source.sourceId,
        ),
      ).toBe(false);
      if (request < 8) expect(status.nextRetryAt!.getTime()).toBeGreaterThan(Date.now());
    }
    expect(await getPurgeStatus(database.db, owner, source.sourceId)).toMatchObject({
      retryExhausted: true,
      nextRetryAt: null,
      retryRequests: 8,
    });
    let refusal: unknown;
    try {
      await withTenantTx(database.db, service(), (tx) =>
        tx
          .update(knowledgePurgeJobs)
          .set({ retryRequests: 0 })
          .where(eq(knowledgePurgeJobs.sourceId, source.sourceId)),
      );
    } catch (error) {
      refusal = error;
    }
    expect(pgCode(refusal)).toBe('42501');
    expect(
      (
        await withTenantTx(database.db, service(), (tx) =>
          tx.select().from(knowledgeSources).where(eq(knowledgeSources.id, source.sourceId)),
        )
      )[0]?.state,
    ).toBe('revoked');
  });
  it('never deletes a different object named by a damaged document row and never counts absent bytes as removed', async () => {
    const source = await upload();
    const canonical = `${owner.organizationId}/knowledge/${source.documentId}`;
    const foreignKey = `${foreign.organizationId}/knowledge/${randomUUID()}`;
    bytes.set(foreignKey, Buffer.from('Generated unrelated tenant bytes'));
    await withTenantTx(database.db, service(), (tx) =>
      tx
        .update(knowledgeDocuments)
        .set({ objectKey: foreignKey })
        .where(eq(knowledgeDocuments.id, source.documentId)),
    );
    await close(source.sourceId);
    await proof(source.sourceId);
    expect((await purge(source.sourceId)).state).toBe('failed');
    expect(bytes.has(foreignKey)).toBe(true);
    await withTenantTx(database.db, service(), (tx) =>
      tx
        .update(knowledgeDocuments)
        .set({ objectKey: canonical })
        .where(eq(knowledgeDocuments.id, source.documentId)),
    );
    await store.delete(canonical);
    await proof(source.sourceId);
    expect(await purge(source.sourceId)).toMatchObject({
      state: 'completed',
      documents: 1,
      blobs: 0,
    });
    expect(bytes.has(foreignKey)).toBe(true);
  });
  it('requires generated-file proof, preserves cumulative counts across holds, and rechecks the final source-locked inventory', async () => {
    const source = await upload();
    await close(source.sourceId);
    await proof(source.sourceId);
    expect(
      (await runSourcePurge(database.db, store, service(), { sourceId: source.sourceId })).state,
    ).toBe('failed');
    expect((await getPurgeStatus(database.db, owner, source.sourceId)).lastErrorCode).toBe(
      'ARTIFACT_PURGE_UNCONFIRMED',
    );
    let status = { removed: 2, remaining: 1, held: 0, confirmed: true },
      finalRemaining = 0;
    const derived: DerivedArtifactPurge = {
      purgeSource: async () => status,
      confirmInTx: async () => ({ remaining: finalRemaining }),
    };
    expect(await purge(source.sourceId, store, derived)).toMatchObject({
      state: 'failed',
      artifacts: 2,
      documents: 0,
    });
    status = { removed: 2, remaining: 0, held: 1, confirmed: true };
    expect(await purge(source.sourceId, store, derived)).toMatchObject({
      state: 'failed',
      artifacts: 2,
      documents: 0,
    });
    expect((await getPurgeStatus(database.db, owner, source.sourceId)).heldArtifacts).toBe(1);
    status = { removed: 3, remaining: 0, held: 0, confirmed: true };
    finalRemaining = 1;
    expect((await purge(source.sourceId, store, derived)).state).toBe('failed');
    finalRemaining = 0;
    const completed = await purge(source.sourceId, store, derived);
    expect(completed).toMatchObject({ state: 'completed', artifacts: 3, documents: 1 });
    expect(await purge(source.sourceId, store, derived)).toEqual(completed);
  });
});
